    function test_canCallApproveOnNonPreciousTokenId() external {
        (
            ArbitraryCallsProposal.ArbitraryCall[] memory calls,
        ) = _createSimpleCalls(1, false);
        (IERC721 preciousToken,) = _pickRandomPreciousToken();
