pragma solidity ^0.8;

import "forge-std/Test.sol";

import "../../contracts/crowdfund/AuctionCrowdfund.sol";
import "../../contracts/crowdfund/BuyCrowdfund.sol";
import "../../contracts/crowdfund/CollectionBuyCrowdfund.sol";
import "../../contracts/globals/Globals.sol";
import "../../contracts/globals/LibGlobals.sol";
import "../../contracts/utils/PartyHelpers.sol";
import "../../contracts/utils/Proxy.sol";

import "../crowdfund/MockMarketWrapper.sol";
import "../crowdfund/TestERC721Vault.sol";
import "../DummyERC721.sol";
import "../TestUtils.sol";

contract CrowdfundHelpers is Test, TestUtils {
    string defaultName = 'AuctionCrowdfund';
    string defaultSymbol = 'PBID';
    uint40 defaultDuration = 60 * 60;
    uint96 defaultMaxBid = 10e18;
    uint96 defaultMaxPrice = 10e18;
    address payable defaultSplitRecipient = payable(0);
    uint16 defaultSplitBps = 0.1e4;
    address defaultInitialDelegate;
    IGateKeeper defaultGateKeeper;
    bytes12 defaultGateKeeperId;
    Crowdfund.FixedGovernanceOpts defaultGovernanceOpts;

    Globals globals;
    AuctionCrowdfund auctionCrowdfundImpl;
    BuyCrowdfund buyCrowdfundImpl;
    CollectionBuyCrowdfund collectionBuyCrowdfundImpl;
    MockMarketWrapper market = new MockMarketWrapper();
    TestERC721Vault erc721Vault = new TestERC721Vault();

    constructor() {
      // create globals
      globals = new Globals(address(this));

      // set partybid crowdfund implementation on globals
      auctionCrowdfundImpl = new AuctionCrowdfund(globals);
      globals.setAddress(LibGlobals.GLOBAL_AUCTION_CF_IMPL, address(auctionCrowdfundImpl));

      // set partybuy crowdfund implementation on globals
      buyCrowdfundImpl = new BuyCrowdfund(globals);
      globals.setAddress(LibGlobals.GLOBAL_BUY_CF_IMPL, address(buyCrowdfundImpl));

      // set partycollectionbuy crowdfund implementation on globals
      collectionBuyCrowdfundImpl = new CollectionBuyCrowdfund(globals);
      globals.setAddress(LibGlobals.GLOBAL_COLLECTION_BUY_CF_IMPL, address(collectionBuyCrowdfundImpl));
    }

    function _createAuctionCrowdfundCrowdfund(
        uint256 auctionId,
        uint256 tokenId,
        uint96 initialContribution
    )
        private
        returns (AuctionCrowdfund pb)
    {
        pb = AuctionCrowdfund(payable(address(new Proxy{ value: initialContribution }(
            auctionCrowdfundImpl,
            abi.encodeCall(
                AuctionCrowdfund.initialize,
                AuctionCrowdfund.AuctionCrowdfundOptions({
                    name: defaultName,
                    symbol: defaultSymbol,
                    auctionId: auctionId,
                    market: market,
                    nftContract: market.nftContract(),
                    nftTokenId: tokenId,
                    duration: defaultDuration,
                    maximumBid: defaultMaxBid,
                    splitRecipient: defaultSplitRecipient,
                    splitBps: defaultSplitBps,
                    initialContributor: address(this),
                    initialDelegate: defaultInitialDelegate,
                    gateKeeper: defaultGateKeeper,
                    gateKeeperId: defaultGateKeeperId,
                    governanceOpts: defaultGovernanceOpts
                })
            )
        ))));
    }

    function _createBuyCrowdfundCrowdfund(uint96 initialContribution)
        private
        returns (BuyCrowdfund pb)
    {
        pb = BuyCrowdfund(payable(address(new Proxy{ value: initialContribution }(
            buyCrowdfundImpl,
            abi.encodeCall(
                BuyCrowdfund.initialize,
                BuyCrowdfund.BuyCrowdfundOptions({
                    name: defaultName,
                    symbol: defaultSymbol,
                    nftContract: erc721Vault.token(),
                    nftTokenId: erc721Vault.mint(),
                    duration: defaultDuration,
                    maximumPrice: defaultMaxPrice,
                    splitRecipient: defaultSplitRecipient,
                    splitBps: defaultSplitBps,
                    initialContributor: address(this),
                    initialDelegate: defaultInitialDelegate,
                    gateKeeper: defaultGateKeeper,
                    gateKeeperId: defaultGateKeeperId,
                    governanceOpts: defaultGovernanceOpts
                })
            )
        ))));
    }

    function _createCollectionBuyCrowdfundCrowdfund(uint96 initialContribution)
        private
        returns (CollectionBuyCrowdfund pb)
    {
        pb = CollectionBuyCrowdfund(payable(address(new Proxy{ value: initialContribution }(
            collectionBuyCrowdfundImpl,
            abi.encodeCall(
                CollectionBuyCrowdfund.initialize,
                CollectionBuyCrowdfund.CollectionBuyCrowdfundOptions({
                    name: defaultName,
                    symbol: defaultSymbol,
                    nftContract: erc721Vault.token(),
                    duration: defaultDuration,
                    maximumPrice: defaultMaxPrice,
                    splitRecipient: defaultSplitRecipient,
                    splitBps: defaultSplitBps,
                    initialContributor: address(this),
                    initialDelegate: defaultInitialDelegate,
                    gateKeeper: defaultGateKeeper,
                    gateKeeperId: defaultGateKeeperId,
                    governanceOpts: defaultGovernanceOpts
                })
            )
        ))));
    }

    function testGetAuctionCrowdfundCrowdfundType() public {
      (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);

      // create partybid crowdfund
      AuctionCrowdfund pbid = _createAuctionCrowdfundCrowdfund(auctionId, tokenId, 0);

      // create party helpers
      PartyHelpers ph = new PartyHelpers();

      PartyHelpers.CrowdfundType cft = ph.getCrowdfundType(address(globals), address(pbid));
      assertEq(uint256(cft), 0);
    }

    function testGetBuyCrowdfundCrowdfundType() public {
      // create partybuy crowdfund
      BuyCrowdfund pbuy = _createBuyCrowdfundCrowdfund(0);

      // create party helpers
      PartyHelpers ph = new PartyHelpers();

      PartyHelpers.CrowdfundType cft = ph.getCrowdfundType(address(globals), address(pbuy));
      assertEq(uint256(cft), 1);
    }

    function testGetCollectionBuyCrowdfundCrowdfundType() public {
      // create partycollectionbuy crowdfund
      CollectionBuyCrowdfund pcb = _createCollectionBuyCrowdfundCrowdfund(0);

      // create party helpers
      PartyHelpers ph = new PartyHelpers();

      PartyHelpers.CrowdfundType cft = ph.getCrowdfundType(address(globals), address(pcb));
      assertEq(uint256(cft), 2);
    }
}
"},"sol-tests/utils/Implementation.t.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8;

import "../../contracts/utils/Implementation.sol";
import "../TestUtils.sol";

contract TestableImplementation is Implementation {
    uint256 public initializeCount;

    constructor() {
        initialize();
    }

    function initialize() public onlyConstructor {
        ++initializeCount;
    }
}

contract ReinitializingImplementation is TestableImplementation {
    constructor() {
        // Attempt to call initialize() again by calling back in.
        // This should be a noop call because the contract has no bytecode
        // during construction.
        address(this).call(abi.encodeCall(this.initialize, ()));
    }
}

contract ImplementationTest is Test, TestUtils {

    function test_cannotInitializeOutsideOfConstructor() external {
        TestableImplementation impl = new TestableImplementation();
        vm.expectRevert(abi.encodeWithSelector(Implementation.OnlyConstructorError.selector));
        impl.initialize();
    }

    function test_cannotReenterReinitialize() external {
        ReinitializingImplementation impl = new ReinitializingImplementation();
        assertEq(impl.initializeCount(), 1);
    }
}
"},"sol-tests/utils/LibSafeERC721.t.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8;

import "../../contracts/utils/LibSafeERC721.sol";
import "../DummyERC721.sol";
import "../TestUtils.sol";

contract EmptyContract { }

contract BadERC721 {
    function ownerOf(uint256) external pure returns (address) { }
}

contract LibSafeERC721Test is TestUtils {
    using LibSafeERC721 for IERC721;

    IERC721 token = new DummyERC721();
    IERC721 eoa = IERC721(vm.addr(1));
    IERC721 emptyContract = IERC721(address(new EmptyContract()));
    IERC721 badERC721 = IERC721(address(new BadERC721()));
    uint256 tokenId = DummyERC721(address(token)).mint(address(this));

    function test_safeOwnerOf_works() external {
        assertEq(token.safeOwnerOf(tokenId), address(this));
    }

    function test_safeOwnerOf_doesntRevertIfTokenIDDoesntExist() external {
        assertEq(token.safeOwnerOf(999), address(0));
    }

    function test_safeOwnerOf_doesntRevertOnEOA() external {
        assertEq(eoa.safeOwnerOf(tokenId), address(0));
    }

    function test_safeOwnerOf_doesntRevertOnEmptyContract() external {
        assertEq(emptyContract.safeOwnerOf(tokenId), address(0));
    }

    function test_safeOwnerOf_doesntRevertOnBadERC721() external {
        assertEq(badERC721.safeOwnerOf(tokenId), address(0));
    }
}"},"sol-tests/utils/PartyGovernanceHelpers.t.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8;

import "forge-std/Test.sol";
import "forge-std/console2.sol";

import "../../contracts/party/PartyFactory.sol";
import "../../contracts/party/Party.sol";
import "../../contracts/globals/Globals.sol";
import "../../contracts/renderers/PartyGovernanceNFTRenderer.sol";
import "../../contracts/utils/PartyHelpers.sol";
import "../proposals/DummySimpleProposalEngineImpl.sol";
import "../proposals/DummyProposalEngineImpl.sol";
import "../TestUtils.sol";
import "../DummyERC721.sol";
import "../TestUsers.sol";
import "../TestUtils.sol";

contract PartyGovernanceHelpersTest is Test, TestUtils {
    PartyFactory partyFactory;
    DummySimpleProposalEngineImpl eng;
    PartyGovernanceNFTRenderer nftRenderer;
    PartyParticipant john;
    PartyParticipant steve;
    PartyParticipant lawrence;
    PartyParticipant anna;
    DummyERC721 toadz;
    PartyAdmin partyAdmin;
    address globalDaoWalletAddress = address(420);

    function setUp() public {
        GlobalsAdmin globalsAdmin = new GlobalsAdmin();
        Globals globals = globalsAdmin.globals();
        Party partyImpl = new Party(globals);
        globalsAdmin.setPartyImpl(address(partyImpl));
        globalsAdmin.setGlobalDaoWallet(globalDaoWalletAddress);

        eng = new DummySimpleProposalEngineImpl();
        globalsAdmin.setProposalEng(address(eng));

        nftRenderer = new PartyGovernanceNFTRenderer(globals);
        globalsAdmin.setGovernanceNftRendererAddress(address(nftRenderer));

        partyFactory = new PartyFactory(globals);

        john = new PartyParticipant();
        steve = new PartyParticipant();
        lawrence = new PartyParticipant();
        anna = new PartyParticipant();

        partyAdmin = new PartyAdmin(partyFactory);

        // Mint dummy NFT
        address nftHolderAddress = address(1);
        toadz = new DummyERC721();
        toadz.mint(nftHolderAddress);
    }

    ///////////////////////////////////
    // PartyGovernance helpers tests //
    ///////////////////////////////////
    function testGetCurrDelegates() public {
        // Create party
        (Party party, ,) = partyAdmin.createParty(
            PartyAdmin.PartyCreationMinimalOptions({
                host1: address(this),
                host2: address(0),
                passThresholdBps: 5100,
                totalVotingPower: 100,
                preciousTokenAddress: address(toadz),
                preciousTokenId: 1,
                feeBps: 0,
                feeRecipient: payable(0)
            })
        );

        // Mint first governance NFTs
        partyAdmin.mintGovNft(party, address(john), 30, address(john));
        partyAdmin.mintGovNft(party, address(steve), 15, address(john));
        partyAdmin.mintGovNft(party, address(lawrence), 20, address(anna));
        partyAdmin.mintGovNft(party, address(anna), 35, address(lawrence));

        // create party helpers
        PartyHelpers ph = new PartyHelpers();

        // test getCurrentDelegates
        address[] memory members = new address[](4);
        members[0] = address(john);
        members[1] = address(steve);
        members[2] = address(lawrence);
        members[3] = address(anna);
        PartyHelpers.MemberAndDelegate[] memory membersAndDelegates = ph.getCurrentDelegates(address(party), members);
        assertTrue(membersAndDelegates.length == 4);
        assertTrue(membersAndDelegates[0].member == address(john));
        assertTrue(membersAndDelegates[0].delegate == address(john));
        assertTrue(membersAndDelegates[1].member == address(steve));
        assertTrue(membersAndDelegates[1].delegate == address(john));
        assertTrue(membersAndDelegates[2].member == address(lawrence));
        assertTrue(membersAndDelegates[2].delegate == address(anna));
        assertTrue(membersAndDelegates[3].member == address(anna));
        assertTrue(membersAndDelegates[3].delegate == address(lawrence));
    }

    function testGetVotingPowersAt() public {
        // Create party
        (Party party, ,) = partyAdmin.createParty(
            PartyAdmin.PartyCreationMinimalOptions({
                host1: address(this),
                host2: address(0),
                passThresholdBps: 5100,
                totalVotingPower: 100,
                preciousTokenAddress: address(toadz),
                preciousTokenId: 1,
                feeBps: 0,
                feeRecipient: payable(0)
            })
        );

        // Mint first governance NFTs
        partyAdmin.mintGovNft(party, address(john), 30, address(john));
        partyAdmin.mintGovNft(party, address(steve), 15, address(steve));
        partyAdmin.mintGovNft(party, address(lawrence), 20, address(lawrence));
        partyAdmin.mintGovNft(party, address(anna), 35, address(anna));

        // create party helpers
        PartyHelpers ph = new PartyHelpers();

        // test getVotingPowersAt
        address[] memory voters = new address[](4);
        voters[0] = address(john);
        voters[1] = address(steve);
        voters[2] = address(lawrence);
        voters[3] = address(anna);
        uint256[] memory indexes = new uint256[](4);
        PartyHelpers.MemberAndVotingPower[] memory membersAndVotingPowers =
            ph.getVotingPowersAt(address(party), voters, uint40(block.timestamp), indexes);
        assertTrue(membersAndVotingPowers.length == 4);
        assertTrue(membersAndVotingPowers[0].member == address(john));
        assertTrue(membersAndVotingPowers[0].votingPower == 30);
        assertTrue(membersAndVotingPowers[1].member == address(steve));
        assertTrue(membersAndVotingPowers[1].votingPower == 15);
        assertTrue(membersAndVotingPowers[2].member == address(lawrence));
        assertTrue(membersAndVotingPowers[2].votingPower == 20);
        assertTrue(membersAndVotingPowers[3].member == address(anna));
        assertTrue(membersAndVotingPowers[3].votingPower == 35);
    }

    //////////////////////////////////////
    // PartyGovernanceNFT helpers tests //
    //////////////////////////////////////
    function testGetNftInfos() public {
        // Create party
        (Party party, ,) = partyAdmin.createParty(
            PartyAdmin.PartyCreationMinimalOptions({
                host1: address(this),
                host2: address(0),
                passThresholdBps: 5100,
                totalVotingPower: 100,
                preciousTokenAddress: address(toadz),
                preciousTokenId: 1,
                feeBps: 0,
                feeRecipient: payable(0)
            })
        );

        // create party helpers
        PartyHelpers ph = new PartyHelpers();

        // test tokenCount = 0
        PartyHelpers.NftInfo[] memory emptyNftInfo = ph.getNftInfos(address(party), 1, 6);
        assertTrue(emptyNftInfo.length == 0);

        // Mint first governance NFTs
        partyAdmin.mintGovNft(party, address(john), 30, address(john));
        partyAdmin.mintGovNft(party, address(steve), 15, address(steve));
        partyAdmin.mintGovNft(party, address(lawrence), 20, address(lawrence));
        partyAdmin.mintGovNft(party, address(anna), 35, address(anna));

        // test endIndex > tokenCount
        PartyHelpers.NftInfo[] memory nftInfos = ph.getNftInfos(address(party), 1, 6);
        assertTrue(nftInfos.length == 4);
        assertTrue(nftInfos[0].tokenId == 1);
        assertTrue(nftInfos[0].owner == address(john));
        assertTrue(nftInfos[0].intrinsicVotingPower == 30);
        assertTrue(nftInfos[1].tokenId == 2);
        assertTrue(nftInfos[1].owner == address(steve));
        assertTrue(nftInfos[1].intrinsicVotingPower == 15);
        assertTrue(nftInfos[2].tokenId == 3);
        assertTrue(nftInfos[2].owner == address(lawrence));
        assertTrue(nftInfos[2].intrinsicVotingPower == 20);
        assertTrue(nftInfos[3].tokenId == 4);
        assertTrue(nftInfos[3].owner == address(anna));
        assertTrue(nftInfos[3].intrinsicVotingPower == 35);

        // test expected startTokenId and endTokenId
        PartyHelpers.NftInfo[] memory nftInfos2 = ph.getNftInfos(address(party), 1, 1);
        assertTrue(nftInfos2.length == 1);
        assertTrue(nftInfos2[0].tokenId == 1);
        assertTrue(nftInfos2[0].owner == address(john));
        assertTrue(nftInfos2[0].intrinsicVotingPower == 30);

        // test startTokenId > 1
        PartyHelpers.NftInfo[] memory nftInfos3 = ph.getNftInfos(address(party), 2, 4);
        assertTrue(nftInfos3.length == 3);
        assertTrue(nftInfos3[0].tokenId == 2);
        assertTrue(nftInfos3[0].owner == address(steve));
        assertTrue(nftInfos3[0].intrinsicVotingPower == 15);
        assertTrue(nftInfos3[1].tokenId == 3);
        assertTrue(nftInfos3[1].owner == address(lawrence));
        assertTrue(nftInfos3[1].intrinsicVotingPower == 20);
        assertTrue(nftInfos3[2].tokenId == 4);
        assertTrue(nftInfos3[2].owner == address(anna));
        assertTrue(nftInfos3[2].intrinsicVotingPower == 35);

        // test startTokenId > 1 and endTokenId > tokenCount
        PartyHelpers.NftInfo[] memory nftInfos4 = ph.getNftInfos(address(party), 2, 6);
        assertTrue(nftInfos4.length == 3);
        assertTrue(nftInfos4[0].tokenId == 2);
        assertTrue(nftInfos4[0].owner == address(steve));
        assertTrue(nftInfos4[0].intrinsicVotingPower == 15);
        assertTrue(nftInfos4[1].tokenId == 3);
        assertTrue(nftInfos4[1].owner == address(lawrence));
        assertTrue(nftInfos4[1].intrinsicVotingPower == 20);
        assertTrue(nftInfos4[2].tokenId == 4);
        assertTrue(nftInfos4[2].owner == address(anna));
        assertTrue(nftInfos4[2].intrinsicVotingPower == 35);
    }
}
